-- Run once in Supabase Dashboard > SQL Editor.
create table if not exists public.admin_users (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);

create table if not exists public.blog_posts (
  id bigint generated by default as identity primary key,
  title text not null,
  slug text not null unique,
  excerpt text not null,
  body text not null,
  category text not null default 'Insights',
  author text not null default 'VisionID Team',
  status text not null default 'draft' check (status in ('draft','published')),
  feature_image text not null default '',
  seo_title text not null default '',
  seo_description text not null default '',
  canonical_url text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists blog_posts_status_created_idx on public.blog_posts(status, created_at desc);

create table if not exists public.enquiries (
  id bigint generated by default as identity primary key,
  kind text not null check (kind in ('contact','lead','partner','career')),
  name text not null,
  email text not null,
  phone text not null default '',
  message text not null default '',
  fields_json jsonb not null default '{}'::jsonb,
  status text not null default 'new' check (status in ('new','in_progress','closed')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists enquiries_created_idx on public.enquiries(created_at desc);
create index if not exists enquiries_status_idx on public.enquiries(status);

create or replace function public.is_visionid_admin()
returns boolean language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $$;
revoke all on function public.is_visionid_admin() from public;
grant execute on function public.is_visionid_admin() to authenticated;

alter table public.admin_users enable row level security;
alter table public.blog_posts enable row level security;
alter table public.enquiries enable row level security;
revoke all on public.admin_users from anon, authenticated;
grant select on public.admin_users to authenticated;

drop policy if exists "Admins read own membership" on public.admin_users;
create policy "Admins read own membership" on public.admin_users
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Public reads published blogs" on public.blog_posts;
create policy "Public reads published blogs" on public.blog_posts
  for select to anon, authenticated using (status = 'published');
drop policy if exists "Admins manage blogs" on public.blog_posts;
create policy "Admins manage blogs" on public.blog_posts
  for all to authenticated using ((select public.is_visionid_admin()))
  with check ((select public.is_visionid_admin()));
drop policy if exists "Visitors submit enquiries" on public.enquiries;
create policy "Visitors submit enquiries" on public.enquiries
  for insert to anon, authenticated
  with check (length(name) between 2 and 120 and length(email) between 3 and 190 and length(message) <= 4000);
drop policy if exists "Admins read enquiries" on public.enquiries;
create policy "Admins read enquiries" on public.enquiries
  for select to authenticated using ((select public.is_visionid_admin()));
drop policy if exists "Admins update enquiries" on public.enquiries;
create policy "Admins update enquiries" on public.enquiries
  for update to authenticated using ((select public.is_visionid_admin()))
  with check ((select public.is_visionid_admin()));
drop policy if exists "Admins delete enquiries" on public.enquiries;
create policy "Admins delete enquiries" on public.enquiries
  for delete to authenticated using ((select public.is_visionid_admin()));

grant select on public.blog_posts to anon, authenticated;
grant insert, update, delete on public.blog_posts to authenticated;
grant insert on public.enquiries to anon, authenticated;
grant select, update, delete on public.enquiries to authenticated;
grant usage, select on sequence public.blog_posts_id_seq to authenticated;
grant usage, select on sequence public.enquiries_id_seq to anon, authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('blog-images','blog-images',true,5242880,array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "Public reads blog images" on storage.objects;
create policy "Public reads blog images" on storage.objects
  for select to public using (bucket_id = 'blog-images');
drop policy if exists "Admins upload blog images" on storage.objects;
create policy "Admins upload blog images" on storage.objects
  for insert to authenticated with check (bucket_id = 'blog-images' and (select public.is_visionid_admin()));
drop policy if exists "Admins update blog images" on storage.objects;
create policy "Admins update blog images" on storage.objects
  for update to authenticated using (bucket_id = 'blog-images' and (select public.is_visionid_admin()))
  with check (bucket_id = 'blog-images' and (select public.is_visionid_admin()));
drop policy if exists "Admins delete blog images" on storage.objects;
create policy "Admins delete blog images" on storage.objects
  for delete to authenticated using (bucket_id = 'blog-images' and (select public.is_visionid_admin()));

